#include <iostream>
#include <algorithm>
#include <numeric>

using namespace std;

using int64 = long long;
using int128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c, h[2], w[2];
    cin >> c >> h[0] >> h[1] >> w[0] >> w[1];

    const int64 g = gcd(w[0], w[1]);
    int128 answer = 0;

    auto updateByFirst = [&](int64 limit) {
        for (int64 x = 0; x <= limit; ++x) {
            int64 y = (c - x * w[0]) / w[1];
            answer = max(answer, int128(x) * h[0] + int128(y) * h[1]);
        }
    };

    auto updateBySecond = [&](int64 limit) {
        for (int64 y = 0; y <= limit; ++y) {
            int64 x = (c - y * w[1]) / w[0];
            answer = max(answer, int128(x) * h[0] + int128(y) * h[1]);
        }
    };

    if (int128(h[0]) * w[1] >= int128(h[1]) * w[0]) {
        int64 allFirst = c / w[0];
        int64 limitedSecond = min(c / w[1], w[0] / g - 1);

        if (allFirst <= limitedSecond)
            updateByFirst(allFirst);
        else
            updateBySecond(limitedSecond);
    } else {
        int64 limitedFirst = min(c / w[0], w[1] / g - 1);
        int64 allSecond = c / w[1];

        if (limitedFirst <= allSecond)
            updateByFirst(limitedFirst);
        else
            updateBySecond(allSecond);
    }

    if (answer == 0) {
        cout << 0 << '\n';
        return 0;
    }

    string result;
    while (answer > 0) {
        result.push_back(char('0' + answer % 10));
        answer /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result << '\n';

    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

using int64 = long long;
using int128 = __int128_t;

int64 gcdll(int64 a, int64 b) {
    while (b) {
        int64 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void printInt128(int128 value) {
    if (value == 0) {
        cout << 0 << '\n';
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c, h[2], w[2];
    cin >> c >> h[0] >> h[1] >> w[0] >> w[1];

    int64 g = gcdll(w[0], w[1]);
    int high = (int128(h[0]) * w[1] >= int128(h[1]) * w[0]) ? 0 : 1;
    int low = high ^ 1;

    int64 allHigh = c / w[high];
    int64 boundedLow = min(c / w[low], w[high] / g - 1);
    int128 answer = 0;

    if (allHigh <= boundedLow) {
        for (int64 highCount = 0;; ++highCount) {
            int64 remaining = c - highCount * w[high];
            int64 lowCount = remaining / w[low];
            answer = max(answer,
                         int128(highCount) * h[high] +
                         int128(lowCount) * h[low]);
            if (highCount == allHigh) break;
        }
    } else {
        for (int64 lowCount = 0;; ++lowCount) {
            int64 remaining = c - lowCount * w[low];
            int64 highCount = remaining / w[high];
            answer = max(answer,
                         int128(highCount) * h[high] +
                         int128(lowCount) * h[low]);
            if (lowCount == boundedLow) break;
        }
    }

    printInt128(answer);
    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 gcd64(int64 a, int64 b) {
    while (b != 0) {
        int64 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void print128(i128 value) {
    if (value == 0) {
        cout << 0 << '\n';
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c, h[2], w[2];
    cin >> c >> h[0] >> h[1] >> w[0] >> w[1];

    if (w[0] < w[1]) {
        swap(w[0], w[1]);
        swap(h[0], h[1]);
    }

    const int64 g = gcd64(w[0], w[1]);
    const int64 period = w[1] / g;
    const int64 m = c / w[0];

    int64 left, right;
    if ((i128)h[0] * w[1] >= (i128)h[1] * w[0]) {
        left = max<int64>(0, m - period + 1);
        right = m;
    } else {
        left = 0;
        right = min<int64>(m, period - 1);
    }

    i128 answer = 0;
    for (int64 x = left; x <= right; ++x) {
        int64 remaining = c - x * w[0];
        i128 value = (i128)x * h[0]
                   + (i128)(remaining / w[1]) * h[1];
        answer = max(answer, value);
    }

    print128(answer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c, h[2], w[2];
    cin >> c >> h[0] >> h[1] >> w[0] >> w[1];

    int64 limit = static_cast<int64>(sqrtl(static_cast<long double>(c)));
    while (static_cast<i128>(limit + 1) * (limit + 1) <= c) ++limit;
    while (static_cast<i128>(limit) * limit > c) --limit;

    i128 ans = 0;

    auto evaluate = [&](int item, int64 count) {
        int other = item ^ 1;
        int64 remaining = c - count * w[item];
        i128 value = static_cast<i128>(count) * h[item]
                   + static_cast<i128>(remaining / w[other]) * h[other];
        ans = max(ans, value);
    };

    if (w[0] > limit) {
        for (int64 count = 0; count <= c / w[0]; ++count)
            evaluate(0, count);
    } else if (w[1] > limit) {
        for (int64 count = 0; count <= c / w[1]; ++count)
            evaluate(1, count);
    } else {
        int64 g = gcd(w[0], w[1]);

        if (static_cast<i128>(h[0]) * w[1] >=
            static_cast<i128>(h[1]) * w[0]) {
            int64 maximum = min(c / w[1], w[0] / g - 1);
            for (int64 count = 0; count <= maximum; ++count)
                evaluate(1, count);
        } else {
            int64 maximum = min(c / w[0], w[1] / g - 1);
            for (int64 count = 0; count <= maximum; ++count)
                evaluate(0, count);
        }
    }

    if (ans == 0) {
        cout << 0;
        return 0;
    }

    string result;
    while (ans > 0) {
        result.push_back(char('0' + ans % 10));
        ans /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result << '\n';

    return 0;
}

